// A fixed thread pool of 4 workers processing 100 image resize tasks
ExecutorService pool = Executors.newFixedThreadPool(4);

for (Image img : images) {          // 100 images queued up
    pool.submit(() -> resize(img)); // each task waits for a free worker
}

pool.shutdown();
pool.awaitTermination(1, TimeUnit.HOURS);
// only 4 threads were ever created, no matter how many images there are

